#include <stdio.h>

// Complete this program to sort the array and print the elements separated by space:

int main() {
    int arr[] = {5, 2, 8, 1, 3};
    int n = 5;

    // Implement sorting algorithm here

    for(int i = 0; i < n; i++) {
        printf("%d%s", arr[i], i == n - 1 ? "" : " ");
    }
    return 0;
}
